// Multipart bodies for `ronja api -F`, so an upload never needs the credential
// in a shell variable for curl. -F is a body ENCODING like -d, not a wrapper: it
// knows nothing about any route.

// formBody is a multipart body as an ordered list of segments: generated bytes
// or a file on disk streamed at send time, so Len is an exact Content-Length and
// file bytes never enter memory. The boundary is baked into the literals once,
// so every Open yields the same bytes, as a retry and the sent Content-Type require.
type formBody struct {
	segments []formSegment
	size     int64
}

type formSegment struct {
	literal []byte
	path    string    // empty for a literal segment
	size    int64     // the file's size at build time
	modTime time.Time // the file's modification time when size was measured
}

func (f formBody) Len() int64 { return f.size }

// Open returns a reader over the whole body, opening each file part LAZILY and
// closing it at EOF, so a form of many files holds one descriptor at a time. An
// unopenable part therefore fails mid-request; checkFormPaths runs first to catch
// the ordinary bad path up front.
func (f formBody) Open() (io.ReadCloser, error) {
	return &formReader{segments: f.segments}, nil
}

type formReader struct {
	segments []formSegment
	next     int
	// open is the file behind current, or nil when the segment is literal bytes.
	current io.Reader
	open    *os.File
	closed  bool
}

func (r *formReader) Read(p []byte) (int, error) {
	if r.closed {
		return 0, os.ErrClosed
	}
	for {
		if r.current == nil {
			if r.next >= len(r.segments) {
				return 0, io.EOF
			}
			seg := r.segments[r.next]
			r.next++
			if seg.path == "" {
				r.current = bytes.NewReader(seg.literal)
				continue
			}
			file, err := os.Open(seg.path)
			if err != nil {
				return 0, err
			}
			r.open, r.current = file, file
			continue
		}
		n, err := r.current.Read(p)
		if err == io.EOF {
			// A close error on a file read to the end says nothing about the
			// bytes already handed over, so it must not fail the upload.
			r.closeCurrent()
			if n > 0 {
				return n, nil
			}
			continue
		}
		if n > 0 || err != nil {
			return n, err
		}
		// A reader may legally return (0, nil); ask it again rather than
		// reporting an EOF it did not give.
	}
}

// Close releases the one descriptor that may still be open: the part being read
// when the request was abandoned.
func (r *formReader) Close() error {
	r.closed = true
	if r.open == nil {
		return nil
	}
	err := r.open.Close()
	r.open, r.current = nil, nil
	return err
}

func (r *formReader) closeCurrent() {
	if r.open != nil {
		_ = r.open.Close()
		r.open = nil
	}
	r.current = nil
}

func (f formBody) paths() []sizedPath {
	var paths []sizedPath
	for _, seg := range f.segments {
		if seg.path != "" {
			paths = append(paths, sizedPath{path: seg.path, size: seg.size, modTime: seg.modTime})
		}
	}
	return paths
}

// buildForm turns repeated curl-style -F specs (name=value, name=@path, with
// `@-` for standard input) into a multipart body and its content type. File parts
// are streamed; a piped part and a readable non-regular path cannot be re-opened
// to the same bytes, so they are buffered (see classifyBodyPath).
func buildForm(specs []string) (api.BodySource, string, error) {
	var (
		buf    bytes.Buffer
		body   formBody
		writer = multipart.NewWriter(&buf)
	)
	// flush must run right after a file part's headers are written, so the
	// file's bytes are spliced in behind them.
	flush := func() {
		if buf.Len() == 0 {
			return
		}
		literal := bytes.Clone(buf.Bytes())
		body.segments = append(body.segments, formSegment{literal: literal})
		body.size += int64(len(literal))
		buf.Reset()
	}

	for _, spec := range specs {
		// FIRST = only: a literal value may contain one.
		name, value, ok := strings.Cut(spec, "=")
		if !ok || name == "" {
			return nil, "", fmt.Errorf("-F takes name=value or name=@path, got %q", spec)
		}

		path, isFile := strings.CutPrefix(value, "@")
		if !isFile {
			if err := writer.WriteField(name, value); err != nil {
				return nil, "", fmt.Errorf("build form field %s: %w", name, err)
			}
			continue
		}
		seg, err := writeFilePart(writer, name, path)
		if err != nil {
			return nil, "", err
		}
		if seg != nil {
			flush()
			body.segments = append(body.segments, *seg)
			body.size += seg.size
		}
	}

	if err := writer.Close(); err != nil {
		return nil, "", fmt.Errorf("finish form body: %w", err)
	}
	flush()
	return body, writer.FormDataContentType(), nil
}

// writeFilePart adds one file part with a content type guessed from the
// extension, not CreateFormFile's hardcoded octet-stream: Ronja stores the
// declared type on the file row, and a PDF stored as octet-stream cannot be
// previewed or have its text extracted. It returns the segment to splice in after
// the part's headers, or nil when the content was buffered and already written.
func writeFilePart(writer *multipart.Writer, name, path string) (*formSegment, error) {
	var (
		buffered []byte // the content, when it had to be read rather than streamed
		streamed bool
		size     int64
		modTime  time.Time
		filename string
	)
	switch {
	case path == "-":
		// A part with no filename is a plain field to most servers, silently
		// dropped by an upload handler looking for a file.
		filename = name
		content, err := readStdinLimit("-F "+name+"=@-", "-F", maxStdinBody)
		if err != nil {
			return nil, err
		}
		buffered = content
	default:
		filename = filepath.Base(path)
		what := "-F " + name + "=@" + path
		kind, fi, err := classifyBodyPath(what, path)
		if err != nil {
			return nil, err
		}
		if kind == pathRegular {
			streamed, size, modTime = true, fi.Size(), fi.ModTime()
			break
		}
		// Not a regular file, but readable: buffered like a pipe (see
		// classifyBodyPath).
		content, err := readUnseekablePath(what, "-F", path)
		if err != nil {
			return nil, err
		}
		buffered = content
	}

	contentType := mime.TypeByExtension(filepath.Ext(filename))
	if contentType == "" {
		contentType = "application/octet-stream"
	}

	header := textproto.MIMEHeader{}
	header.Set("Content-Disposition", fmt.Sprintf(`form-data; name="%s"; filename="%s"`,
		escapeFormValue(name), escapeFormValue(filename)))
	header.Set("Content-Type", contentType)

	part, err := writer.CreatePart(header)
	if err != nil {
		return nil, fmt.Errorf("build form file %s: %w", name, err)
	}
	if streamed {
		return &formSegment{path: path, size: size, modTime: modTime}, nil
	}
	if _, err := part.Write(buffered); err != nil {
		return nil, fmt.Errorf("build form file %s: %w", name, err)
	}
	return nil, nil
}

// formValueEscaper quotes a name or filename for a Content-Disposition header,
// as mime/multipart does internally: a quote or newline in a (possibly
// attacker-chosen) filename would otherwise end the header and inject more.
var formValueEscaper = strings.NewReplacer("\\", "\\\\", `"`, "\\\"", "\r", "", "\n", "")

func escapeFormValue(s string) string { return formValueEscaper.Replace(s) }

// checkStdinSources refuses more than one reader of standard input: a pipe
// drains once, so every later reader would silently send an empty part that the
// server accepts.
func checkStdinSources(data string, specs []string) error {
	var sources []string
	if data == "@-" {
		sources = append(sources, "-d @-")
	}
	for _, spec := range specs {
		name, value, ok := strings.Cut(spec, "=")
		if ok && value == "@-" {
			sources = append(sources, "-F "+name+"=@-")
		}
	}
	if len(sources) > 1 {
		return fmt.Errorf("%s all read standard input, and only the first would get anything — a pipe can be drained once, so the rest would be sent as empty",
			strings.Join(sources, ", "))
	}
	return nil
}

// formContentType decides what Content-Type a multipart request goes out with.
// A supplied multipart type keeps its subtype and parameters but always gets the
// generated boundary (a foreign one parses as zero parts and silently "succeeds");
// a supplied non-multipart type is refused.
func formContentType(supplied, generated string) (string, error) {
	if supplied == "" {
		return generated, nil
	}
	mediaType, params, err := mime.ParseMediaType(supplied)
	if err != nil {
		return "", fmt.Errorf("cannot read the Content-Type given with -H (%q): %w", supplied, err)
	}
	if !strings.HasPrefix(mediaType, "multipart/") {
		return "", fmt.Errorf("-F builds a multipart body, but -H declared Content-Type %q — drop the header, or send the bytes yourself with -d",
			mediaType)
	}
	_, generatedParams, err := mime.ParseMediaType(generated)
	if err != nil {
		// Cannot happen: `generated` is mime/multipart's own output.
		return generated, nil //nolint:nilerr // the generated type is always usable
	}
	if params == nil {
		params = map[string]string{}
	}
	params["boundary"] = generatedParams["boundary"]
	return mime.FormatMediaType(mediaType, params), nil
}

// checkFormPaths reports a -F file that does not exist, or is a directory,
// BEFORE anything is sent: formBody opens parts lazily, so otherwise the failure
// lands mid-request (with --retry, after the retry budget is spent). It only
// stats, because reading a non-regular path would drain what the build is about
// to read.
func checkFormPaths(specs []string) error {
	for _, spec := range specs {
		_, value, ok := strings.Cut(spec, "=")
		if !ok {
			continue
		}
		path, isFile := strings.CutPrefix(value, "@")
		if !isFile || path == "-" {
			continue
		}
		if _, _, err := classifyBodyPath("-F "+spec, path); err != nil {
			return err
		}
	}
	return nil
}
